import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_pooled_flag_rate_weights_transcripts():
    groups = {
        "a": [{"flagged": True}],
        "b": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_empty(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 6), (3, 7), (10, 7)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 4], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_parse_transcript_log_flags_and_whitespace():
    assert parse_transcript_log([" a , 3 , 1 \n", "b, -2, 0", " c,4, \t"]) == [
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 4, "flagged": None},
    ]


def test_parse_transcript_log_skips_blanks_and_comments():
    lines = ["", " \t\n", "# comment", " \t# another,comment", "x,1,0", "\n"]
    assert parse_transcript_log(iter(lines)) == [{"id": "x", "day": 1, "flagged": False}]
    assert parse_transcript_log(["", " # only a comment"]) == []


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,no,1", "x,1.5,0", "x,,1"])
@pytest.mark.parametrize("prefix", [[], ["", "  # comment", " \t", "ok,1,1"]])
def test_parse_transcript_log_errors_include_input_line_number(bad_line, prefix):
    with pytest.raises(ValueError, match=rf"\bline {len(prefix) + 1}\b"):
        parse_transcript_log(prefix + [bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id():
    earlier = {"id": "a", "day": 10, "flagged": True}
    later = {"id": "a", "day": 1, "flagged": None}
    b = {"id": "b", "day": 1, "flagged": False}
    c = {"id": "c", "day": 0, "flagged": True}
    events = [earlier, b, c, later]
    assert dedupe_transcripts(events) == [c, later, b]
    assert events == [earlier, b, c, later]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_and_gaps():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1)["groups"] == 1


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (20, 2)])
def test_monitor_summary_calendar_window_and_rounding(days, recent):
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [
            {"day": 4, "flagged": True},
            {"day": 5, "flagged": None},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_ranking_ties_and_empty_groups():
    groups = {
        "z": [{"flagged": True}, {"flagged": False}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": None}],
        "best": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 2) == ["best", "a"]
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 1) == []
    assert top_flagged_groups({}, 1) == []


def test_flag_rate_by_group_sorted_with_empty_groups():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "b": [{"flagged": False}],
        "a": [],
    }
    rates = flag_rate_by_group(groups)
    assert rates == {"a": None, "b": 0.0, "z": 0.5}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize("counts, expected", [
    ([], 0),
    ([0, -1, 0], 0),
    ([1, 2, 0, 3, 4, 5], 3),
    ([1, 2, -1, 3, 4], 2),
    ([1, 2, 3, 0, 1], 3),
])
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
